import{_ as a,o,c as i,a2 as s}from"./chunks/framework.DncwoWA8.js";const p=JSON.parse('{"title":"Coding","description":"","frontmatter":{"title":"Coding"},"headers":[],"relativePath":"groups/coding.md","filePath":"groups/coding.md"}'),t={name:"groups/coding.md"};function r(n,e,l,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="coding" tabindex="-1">Coding <a class="header-anchor" href="#coding" aria-label="Permalink to &quot;Coding&quot;">​</a></h1><p>Scaffold, implement, test, diagnose, simplify, and review code.</p><p>Choose by the task you have now. These are the collection&#39;s groups, including external recommendations. They are not a mandatory delivery pipeline.</p><h2 id="coding-1" tabindex="-1"><a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a> <a class="header-anchor" href="#coding-1" aria-label="Permalink to &quot;[`coding`](/skills/coding)&quot;">​</a></h2><p>Design, implement, refactor, review, or test code under project conventions, risk-based security, and behavior-focused checks.</p><p><strong>Choose it when:</strong> You are designing, implementing, refactoring, reviewing, or testing source code under project conventions.</p><h2 id="coding-with-rules" tabindex="-1"><a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> <a class="header-anchor" href="#coding-with-rules" aria-label="Permalink to &quot;[`coding-with-rules`](/skills/coding-with-rules)&quot;">​</a></h2><p>Language-aware coding: resolve the base workflow, then select rules for the languages and file extensions being changed.</p><p><strong>Choose it when:</strong> Code or toolchain work needs the base coding workflow plus rules for its actual languages and extensions.</p><h2 id="scaffold" tabindex="-1"><a href="/projects/ai-skills/skills/scaffold.html"><code>scaffold</code></a> <a class="header-anchor" href="#scaffold" aria-label="Permalink to &quot;[`scaffold`](/skills/scaffold)&quot;">​</a></h2><p>Create source skeletons for an approved feature, validate their structure, and stop before implementing behavior.</p><p><strong>Choose it when:</strong> An approved feature needs reviewable source skeletons before its behavior is implemented.</p><h2 id="code-review" tabindex="-1"><a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;[`code-review`](/skills/code-review)&quot;">​</a></h2><p>Review the changes since a fixed point (commit, branch, tag, or merge-base) along two axes: Standards (does the code follow this repo&#39;s documented coding standards?) and Spec (does the code match what the originating issue/spec asked for?). Runs both reviews in parallel sub-agents and reports them side by side. Use when the user wants to review a branch, a PR, work-in-progress changes, or asks to &quot;review since X&quot;.</p><p><strong>Choose it when:</strong> You want changes since a fixed commit, branch, tag, or merge-base checked against both standards and the originating specification.</p><h2 id="systematic-debugging" tabindex="-1"><a href="/projects/ai-skills/skills/systematic-debugging.html"><code>systematic-debugging</code></a> <a class="header-anchor" href="#systematic-debugging" aria-label="Permalink to &quot;[`systematic-debugging`](/skills/systematic-debugging)&quot;">​</a></h2><p>Diagnose bugs, failing tests, regressions, flaky behavior, and unexpected results through evidence, root-cause tracing, and single-hypothesis experiments before proposing fixes. Use for debugging in any language, including failures across component or environment boundaries.</p><p><strong>Choose it when:</strong> A bug, regression, failing test, flaky result, or unexpected behavior needs a root cause rather than a guessed patch.</p><h2 id="tdd" tabindex="-1"><a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> <a class="header-anchor" href="#tdd" aria-label="Permalink to &quot;[`tdd`](/skills/tdd)&quot;">​</a></h2><p>Test-driven development. Use when the user wants to build features or fix bugs test-first, mentions &quot;red-green-refactor&quot;, or wants integration tests.</p><p><strong>Choose it when:</strong> You explicitly want test-first feature or bug work, or integration-test slices through public behavior.</p><h2 id="debloat" tabindex="-1"><a href="/projects/ai-skills/skills/debloat.html"><code>debloat</code></a> <a class="header-anchor" href="#debloat" aria-label="Permalink to &quot;[`debloat`](/skills/debloat)&quot;">​</a></h2><p>Prevent overengineering during design; simplify existing code, configuration, or dependencies while preserving required behavior, contracts, security, and operational needs.</p><p><strong>Choose it when:</strong> A design risks unnecessary machinery or existing code and configuration have complexity that no longer earns its cost.</p><h2 id="try-a-workflow" tabindex="-1">Try a workflow <a class="header-anchor" href="#try-a-workflow" aria-label="Permalink to &quot;Try a workflow&quot;">​</a></h2><ul><li><a href="/projects/ai-skills/workflows/implement-a-small-change.html">Implement a small approved change</a> — The requested behavior and authority to change it are already clear.</li><li><a href="/projects/ai-skills/workflows/build-test-first.html">Build one behavior slice test-first</a> — The owner explicitly wants test-first development and the behavior is agreed.</li><li><a href="/projects/ai-skills/workflows/diagnose-a-failure.html">Find the root cause before proposing a fix</a> — A test, build, runtime result, or previously working behavior fails unexpectedly.</li><li><a href="/projects/ai-skills/workflows/scaffold-without-implementation.html">Create a skeleton and stop</a> — A feature&#39;s source structure needs review before behavioral implementation.</li><li><a href="/projects/ai-skills/workflows/simplify-a-design.html">Remove complexity without removing requirements</a> — Existing machinery or a proposed design is harder than the required behavior needs.</li><li><a href="/projects/ai-skills/workflows/review-against-standards-and-spec.html">Review a fixed diff from two perspectives</a> — A branch or change needs standards and specification review against a clear baseline.</li></ul>',26)])])}const u=a(t,[["render",r]]);export{p as __pageData,u as default};
